package org.marketreview.nativeapp;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import org.json.*;
final class DataSafetyChecks {
 interface Try{void run()throws Exception;}
 static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
 static void refuses(Try f)throws Exception{boolean failed=false;try{f.run();}catch(Exception e){failed=true;}check(failed,"expected refusal");}
 static JSONObject fixture()throws Exception{JSONObject o=new JSONObject().put("schema","native-business-v1").put("createdAt","2000-01-01T00:00:00Z");for(String k:DataSafetyModel.KINDS)o.put(k,new JSONArray());o.getJSONArray("accounts").put(new JSONObject().put("id","local").put("name","我的账本").put("type","ledger")).put(new JSONObject().put("id","paper").put("name","纸面模拟").put("type","paper"));return o;}
 static JSONObject model()throws Exception{JSONObject before=fixture(),settings=DataSafetyModel.defaults();String source=DataSafetyModel.json(before);byte[] bytes=source.getBytes(StandardCharsets.UTF_8);JSONObject plan=DataSafetyModel.inspect(bytes,settings,before,DataSafetyModel.sha(bytes),"business.json");check(plan.getBoolean("policyAllowed")&&!plan.getBoolean("eligible")&&plan.getString("checksumState").equals("matched"),"not eligible before isolated validation");refuses(()->DataSafetyModel.inspect(bytes,settings,before,String.join("",java.util.Collections.nCopies(64,"0")),"business.json"));JSONObject strict=SourceAnalysisPacket.copy(settings).put("requireExternalChecksum",true);check(!DataSafetyModel.inspect(bytes,strict,before,"","business.json").getBoolean("policyAllowed"),"external checksum setting consumed");JSONObject partial=SourceAnalysisPacket.copy(before);partial.remove("topics");partial.remove("relations");partial.remove("collections");byte[] p=DataSafetyModel.json(partial).getBytes(StandardCharsets.UTF_8);check(!DataSafetyModel.inspect(p,settings,before,"","old-four.json").getBoolean("policyAllowed"),"partial blocked default");check(DataSafetyModel.inspect(p,SourceAnalysisPacket.copy(settings).put("allowPartialBusinessBackup",true),before,"","old-four.json").getBoolean("policyAllowed"),"explicit partial setting consumed");JSONObject secret=SourceAnalysisPacket.copy(before).put("apiKey","synthetic-do-not-log");refuses(()->DataSafetyModel.inspect(DataSafetyModel.json(secret).getBytes(StandardCharsets.UTF_8),settings,before,"","bad.json"));refuses(()->DataSafetyModel.safeDraft("{\"apiKey\":\"synthetic-do-not-persist\"}"));refuses(()->DataSafetyModel.inspect("{'schema':'bad'}".getBytes(StandardCharsets.UTF_8),settings,before,"","bad.json"));JSONObject legacy=new JSONObject().put("version",8).put("tables",new JSONObject().put("watchlist",new JSONArray()));refuses(()->DataSafetyModel.inspect(DataSafetyModel.json(legacy).getBytes(StandardCharsets.UTF_8),settings,before,"","incomplete-v8.json"));JSONObject privatePlan=SourceAnalysisPacket.copy(plan).put("incoming",new JSONObject().put("privateData","PRIVATE-DO-NOT-EXPORT")).put("raw","PRIVATE-DO-NOT-EXPORT");JSONObject exported=DataSafetyModel.receipt(privatePlan,new JSONObject().put("entries",new JSONArray().put(new JSONObject().put("id","safe").put("privateData","PRIVATE-DO-NOT-EXPORT"))));check(!DataSafetyModel.json(exported).contains("PRIVATE-DO-NOT-EXPORT")&&!exported.getJSONObject("plan").has("incoming"),"summary export excludes private raw/incoming/body");return new JSONObject().put("before",before).put("source",source).put("expectedSha",DataSafetyModel.sha(bytes)).put("plan",plan);}
 public static void main(String[] args)throws Exception{JSONObject result=model();if(args.length>0)Files.write(new File(args[0]).toPath(),DataSafetyModel.json(result).getBytes(StandardCharsets.UTF_8));System.out.println("PASS data safety production Java model hash/consumed policies/partial/credentials refusal/legacy coverage/strict JSON; no device/DB/source write");}
 static void run(FlowInstrumentation f)throws Exception{model();JSONObject before=f.activity.businessStore.backup();String unchanged=DataSafetyModel.baselineHash(before);byte[] source=DataSafetyModel.json(before).getBytes(StandardCharsets.UTF_8);JSONObject plan=DataSafetyModel.validateIsolated(f.activity,DataSafetyModel.inspect(source,DataSafetyModel.defaults(),before,DataSafetyModel.sha(source),"business.json"),before);check(plan.getBoolean("eligible")&&DataSafetyModel.baselineHash(f.activity.businessStore.backup()).equals(unchanged),"isolated validation never writes source business");File file=f.activity.getDatabasePath("data-safety-checks-"+System.nanoTime()+".sqlite");DataSafetyStore store=new DataSafetyStore(file);JSONObject staged=store.stage(plan,source,"");check(java.util.Arrays.equals(store.source(staged.getString("recordRevision")),source),"raw byte identity persisted separately");refuses(()->store.stage(plan,source,"stale"));File missing=new File(f.activity.getCacheDir(),"missing-data-safety-"+System.nanoTime()+".sqlite");JSONObject diagnosed=DataSafetyModel.diagnose(new JSONObject().put("id","missing").put("path",missing.getPath()).put("format","sqlite"),true);check(!diagnosed.getBoolean("present")&&!missing.exists(),"read-only diagnostics never creates missing DB");f.ui(()->{try{DataSafetyScreen panel=new DataSafetyScreen(f.activity,f.activity.businessStore,file,null,null);panel.input.setText("recoverable nonsecret draft");DataSafetyScreen recreated=new DataSafetyScreen(f.activity,f.activity.businessStore,file,null,null);check(recreated.input.getText().toString().equals("recoverable nonsecret draft")&&recreated.plan.optBoolean("eligible"),"draft and already-validated file plan restore");recreated.setDarkTheme(true);recreated.read("完整核验摘要");check(recreated.back()&&!recreated.back(),"internal reader/back preserves main controls");}catch(Exception e){throw new RuntimeException(e);}});}
}

